# Rebuilt 2026-09-14 against tuned225 matrix; source: /home/gaga/huzhan/MSI_ALL_aligned_11samples_consensus0.1Da/spatial_metabolite_modules_10samples/5A_step4_module_activity_spatial_organization.R
# 5A Step 4: pixel-level module activity and spatial organization
local({
suppressPackageStartupMessages({library(data.table);library(matrixStats);library(igraph);library(ggplot2);library(pheatmap)})
BASE<-'/home/gaga/huzhan/MSI_ALL_aligned_10samples_consensus_tuned225';OUT<-file.path(BASE,'spatial_metabolite_modules_10samples_tuned225');S4<-file.path(OUT,'step4_module_activity_spatial_organization');dir.create(S4,recursive=TRUE,showWarnings=FALSE)
mod<-readRDS(file.path(OUT,'step3_modules','MSI_consensus_modules.rds'));reps<-as.data.table(mod$representatives);reps<-reps[module!='grey'];modules<-sort(unique(reps$module));fi<-reps$feature_index
m0<-readRDS(file.path(BASE,'intratumor_spatial_heterogeneity_10samples_part1_consensus_tuned225','tumor_pixels_within_sample_consensus_domains.rds'));keepcols<-c('original_pixel_row','sample_id','diagnosis','source_id','x','y','raw_tic','detected_peak_count','alignment_nmatch');meta<-as.data.table(m0)[,..keepcols];meta[,sample_id:=as.character(sample_id)];meta[,source_id:=as.character(source_id)];setorder(meta,original_pixel_row);rm(m0)
Xall<-readRDS(file.path(BASE,'pixel_by_feature_matrix_aligned_logCPM.rds'));X<-as.matrix(Xall[meta$original_pixel_row,fi,drop=FALSE]);rm(Xall);gc();safez<-function(v){s<-sd(v,na.rm=TRUE);if(!is.finite(s)||s<1e-10)return(rep(0,length(v)));as.numeric(scale(v))}
score<-matrix(NA_real_,nrow(meta),length(modules),dimnames=list(NULL,modules));support<-list();samples<-sort(unique(meta$sample_id))
for(s in samples){ii<-which(meta$sample_id==s);md<-meta[ii];Y<-X[ii,,drop=FALSE];D<-cbind(1,safez(log1p(md$raw_tic)),safez(md$detected_peak_count),safez(md$alignment_nmatch));R<-qr.resid(qr(D),Y);Z<-apply(R,2,safez);ck<-readRDS(file.path(OUT,'step2_spatial_consensus','sample_correlations',paste0(gsub('[^A-Za-z0-9]+','_',s),'_block10.rds')));ev<-ck$evaluable[match(fi,ck$feature_index)];for(mm in modules){jj<-which(reps$module==mm & ev);score[ii,mm]<-rowMeans(Z[,jj,drop=FALSE]);support[[length(support)+1L]]<-data.table(sample=s,module=mm,n_module_features=nrow(reps[module==mm]),n_evaluable_features=length(jj),score_sd=sd(score[ii,mm]))};cat('STEP4_SCORE',s,'\n')}
scoredt<-cbind(meta[,.(original_pixel_row,sample_id,diagnosis,source_id,x,y)],as.data.table(score));fwrite(scoredt,file.path(S4,'pixel_module_activity_scores.csv'));saveRDS(list(pixel_metadata=meta[,.(original_pixel_row,sample_id,diagnosis,source_id,x,y)],scores=score,score_definition='mean of within-sample z-scored technical residuals across representative MSI features evaluable in that sample',modules=modules),file.path(S4,'pixel_module_activity_scores.rds'));fwrite(rbindlist(support),file.path(S4,'module_score_feature_support_by_sample.csv'))
# Four-neighbor spatial graph within source partitions.
make_edges<-function(md){out<-lapply(split(seq_len(nrow(md)),md$source_id),function(ii){k<-paste(md$x[ii],md$y[ii],sep=':');jr<-match(paste(md$x[ii]+1,md$y[ii],sep=':'),k);ju<-match(paste(md$x[ii],md$y[ii]+1,sep=':'),k);rbind(cbind(ii[which(!is.na(jr))],ii[jr[!is.na(jr)]]),cbind(ii[which(!is.na(ju))],ii[ju[!is.na(ju)]]))});do.call(rbind,out)}
spmetrics<-list();cors<-array(NA_real_,c(length(modules),length(modules),length(samples)),dimnames=list(modules,modules,samples));hotj<-cors
for(s in samples){ii<-which(meta$sample_id==s);md<-meta[ii];E<-make_edges(md);S<-score[ii,,drop=FALSE];cors[,,s]<-cor(S,method='spearman',use='pairwise.complete.obs');H<-apply(S,2,function(v)v>=quantile(v,.8,na.rm=TRUE));hotj[,,s]<-outer(seq_along(modules),seq_along(modules),Vectorize(function(a,b)sum(H[,a]&H[,b])/sum(H[,a]|H[,b])));for(k in seq_along(modules)){v<-S[,k];z<-v-mean(v,na.rm=TRUE);okedge<-is.finite(z[E[,1]])&is.finite(z[E[,2]]);ee<-E[okedge,,drop=FALSE];moran<-length(v)/nrow(ee)*sum(z[ee[,1]]*z[ee[,2]],na.rm=TRUE)/sum(z^2,na.rm=TRUE);hot<-H[,k]&is.finite(v);he<-ee[hot[ee[,1]]&hot[ee[,2]],,drop=FALSE];vid<-which(hot);if(length(vid)){g<-make_empty_graph(n=length(vid),directed=FALSE);pos<-setNames(seq_along(vid),vid);if(nrow(he))g<-add_edges(g,as.vector(t(cbind(pos[as.character(he[,1])],pos[as.character(he[,2])]))));cs<-components(g)$csize}else cs<-numeric();spmetrics[[length(spmetrics)+1L]]<-data.table(sample=s,module=modules[k],n_pixels=length(v),n_neighbor_edges=nrow(ee),moran_I=moran,hotspot_threshold=quantile(v,.8,na.rm=TRUE),hotspot_pixels=sum(hot),hotspot_components=length(cs),largest_hotspot_fraction=if(length(cs))max(cs)/sum(hot)else NA_real_,score_q10=quantile(v,.1,na.rm=TRUE),score_q50=median(v,na.rm=TRUE),score_q90=quantile(v,.9,na.rm=TRUE))};cat('STEP4_SPATIAL',s,'edges',nrow(E),'\n')}
sp<-rbindlist(spmetrics);fwrite(sp,file.path(S4,'module_spatial_metrics_by_sample.csv'));medcor<-apply(cors,c(1,2),median,na.rm=TRUE);medhot<-apply(hotj,c(1,2),median,na.rm=TRUE);ms<-sp[,.(median_moran_I=median(moran_I),min_moran_I=min(moran_I),positive_moran_samples=sum(moran_I>0),median_hotspot_components=median(hotspot_components),median_largest_hotspot_fraction=median(largest_hotspot_fraction)),by=module];sup<-rbindlist(support)[,.(min_evaluable_features=min(n_evaluable_features),median_evaluable_features=median(n_evaluable_features)),by=module];ms<-merge(ms,sup,by='module');ms<-merge(ms,fread(file.path(OUT,'step3_modules','module_summary.csv')),by='module');setorder(ms,-median_moran_I);fwrite(ms,file.path(S4,'module_spatial_organization_summary.csv'));saveRDS(list(per_sample_module_metrics=sp,median_module_score_spearman=medcor,median_hotspot_jaccard=medhot,per_sample_score_correlations=cors,per_sample_hotspot_jaccard=hotj,module_summary=ms),file.path(S4,'module_spatial_organization.rds'))
pdf(file.path(S4,'all_module_activity_maps_20pages.pdf'),width=12,height=7);pal<-hcl.colors(100,'Blue-Red 3');for(mm in modules){par(mfrow=c(2,5),mar=c(1.5,1.5,2,1));for(s in samples){ii<-which(meta$sample_id==s);v<-score[ii,mm];lim<-quantile(abs(v),.98,na.rm=TRUE);cc<-pal[pmax(1,pmin(100,floor((v+lim)/(2*lim)*99)+1))];plot(meta$x[ii],-meta$y[ii],pch=15,cex=.28,col=cc,asp=1,axes=FALSE,xlab='',ylab='',main=s);box()};mtext(paste(mm,'module activity (within-sample scale)'),outer=TRUE,line=-1.2,cex=1.1)};dev.off()
pdf(file.path(S4,'step4_spatial_summary.pdf'),width=10,height=8);p<-ggplot(sp,aes(x=reorder(module,moran_I,FUN=median),y=moran_I))+geom_boxplot(fill='#80B1D3',outlier.size=.8)+geom_hline(yintercept=0,lty=2)+coord_flip()+labs(x=NULL,y="Moran's I",title='Spatial autocorrelation of MSI module activity across 10 samples')+theme_bw(base_size=11);print(p);pheatmap(medcor,main='Median cross-sample module-score Spearman correlation',border_color=NA);pheatmap(medhot,main='Median hotspot Jaccard overlap',border_color=NA);dev.off()
writeLines(c('Pixel activity is the mean of within-sample standardized technical residuals for the frozen representative features in each module.','No spatial smoothing is used for the primary score maps.','Spatial organization is summarized by four-neighbor Moran I and top-20-percent hotspot connectivity within source partitions.','Module-module coordination is summarized separately in each physical sample and then by the cross-sample median.','No domain labels or LC-MS/MS are read.'),file.path(S4,'README.txt'))
cat('STEP4_COMPLETE\n');print(ms[,.(module,n_representative_features,median_moran_I,min_moran_I,positive_moran_samples,median_largest_hotspot_fraction,min_alt_cut_jaccard)]);cat('OUT=',S4,'\n');rm(X);gc()
})
